    let want: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let out: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let tmp: &mut crate::port::Cells = &mut crate::port::Cells::new();
    nt_lit(&crate::testport::text_blob("0071 0307 0323")[..], src);
    nt_lit(&crate::testport::text_blob("0071 0323 0307")[..], want);
    crate::testport::assert_eq(nt_nfc_is(src, want, out, tmp), 1, "q dot-above dot-below -> q dot-below dot-above");
    nt_lit(&crate::testport::text_blob("0061 0307 0323")[..], src);
    nt_lit(&crate::testport::text_blob("1EA1 0307")[..], want);
    crate::testport::assert_eq(nt_nfc_is(src, want, out, tmp), 1, "a dot-above dot-below -> U+1EA1 dot-above");
